import{_t as e,it as t,n,rt as r}from"./chunks/framework.wyZghjns.js";var i=JSON.parse(`{"title":"@jsprismarine/console","description":"","frontmatter":{},"headers":[],"relativePath":"api/@jsprismarine/console/index.md","filePath":"api/@jsprismarine/console/index.md"}`),a={name:`api/@jsprismarine/console/index.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<p><a href="./../../">JSPrismarine</a> / @jsprismarine/console</p><h1 id="jsprismarine-console" tabindex="-1">@jsprismarine/console <a class="header-anchor" href="#jsprismarine-console" aria-label="Permalink to “@jsprismarine/console”">​</a></h1><p><a href="https://discord.gg/6w8JWhy" target="_blank" rel="noreferrer"><img src="https://img.shields.io/discord/704967868885762108?color=%237289DA&amp;label=Discord" alt="Join the Discord Server"></a><a href="https://www.npmjs.com/package/@jsprismarine/console" target="_blank" rel="noreferrer"><img src="https://img.shields.io/npm/dt/@jsprismarine/console" alt="npm"></a></p><p>Terminal user interface for the JSPrismarine server console, built on <a href="https://opentui.com" target="_blank" rel="noreferrer">OpenTUI</a>.</p><p>The server entry point in <code>@jsprismarine/server</code> imports this package lazily, and only when it has decided to run the UI: stdin and stdout are a terminal, <code>JSP_NO_TUI</code> and <code>--no-tui</code> are absent, and Node can load <code>node:ffi</code> (26.9 or newer, or 26.4 with <code>--experimental-ffi</code>). In every other situation the server uses its plain line console and this package is never loaded, so a Docker image or a hosting panel pays nothing for it. The UI talks to the server over the messages in <code>@jsprismarine/console-protocol</code>; nothing outside this package imports <code>@opentui/core</code>.</p><p>Requires Node.js 26.9 or later, or 26.4 and later started with <code>--experimental-ffi</code>: OpenTUI calls its native renderer through <code>node:ffi</code>, which shipped in 26.4 behind a flag and is on by default from 26.9. Older versions can&#39;t load the renderer, which is why the server falls back to the plain console instead of failing.</p><h2 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to “Layout”">​</a></h2><p>Each component is a factory in its own file, <code>create&lt;Name&gt;(ctx, props)</code>, with a sibling <code>*.test.ts</code>. Logic that doesn&#39;t need a renderer (log windowing, history, completion, segment truncation) lives in plain modules with their own tests.</p><table tabindex="0"><thead><tr><th>Directory</th><th>Owns</th></tr></thead><tbody><tr><td><code>src/theme/</code></td><td>Color roles resolved against the terminal&#39;s capabilities, and styled text with Minecraft <code>§</code> codes</td></tr><tr><td><code>src/log/</code></td><td>The log store (a ring buffer), the windowed view over it, line formatting, and badges</td></tr><tr><td><code>src/input/</code></td><td>The input bar, command history, and completion state</td></tr><tr><td><code>src/status/</code></td><td>The status bar, its segments, and toasts</td></tr><tr><td><code>src/help/</code></td><td>The help overlay generated from the key map</td></tr><tr><td><code>src/app/</code></td><td>Layout, breakpoints, focus, and wiring; exports <code>startConsole</code></td></tr></tbody></table><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to “Tests”">​</a></h2><p>From the repository root, <code>pnpm exec vitest run packages/console</code> runs this package&#39;s tests. They render into OpenTUI&#39;s test renderer, so they need a Node that loads <code>node:ffi</code> too.</p><h2 id="interfaces" tabindex="-1">Interfaces <a class="header-anchor" href="#interfaces" aria-label="Permalink to “Interfaces”">​</a></h2><ul><li><a href="./interfaces/ConsoleHandle.html">ConsoleHandle</a></li><li><a href="./interfaces/StartConsoleOptions.html">StartConsoleOptions</a></li></ul><h2 id="variables" tabindex="-1">Variables <a class="header-anchor" href="#variables" aria-label="Permalink to “Variables”">​</a></h2><ul><li><a href="./variables/CONSOLE_VERSION.html">CONSOLE_VERSION</a></li></ul><h2 id="functions" tabindex="-1">Functions <a class="header-anchor" href="#functions" aria-label="Permalink to “Functions”">​</a></h2><ul><li><a href="./functions/startConsole.html">startConsole</a></li></ul>`,17)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};